-- Otomatik üretildi: scripts/generate_seed.py
-- Kaynak: Supabase production içerik anlık görüntüsü (2026-08-13).
-- Kullanıcı verileri (profiles, topic_free_attempts, question_feedback) bu dosyada yoktur.
begin;

on conflict (id) do update set title=excluded.title, subtitle=excluded.subtitle, icon=excluded.icon, icon_class=excluded.icon_class, sort_order=excluded.sort_order;

on conflict (id) do update set category_id=excluded.category_id, parent_id=excluded.parent_id, type=excluded.type, title=excluded.title, document_number=excluded.document_number, article_range=excluded.article_range, article_count=excluded.article_count, question_count=excluded.question_count, kadrolar=excluded.kadrolar, sort_order=excluded.sort_order, source_file=excluded.source_file, summary=excluded.summary, key_points=excluded.key_points, show_in_catalog=excluded.show_in_catalog;

on conflict (id) do update set topic_id=excluded.topic_id, prompt=excluded.prompt, options=excluded.options, answer_index=excluded.answer_index, explanation=excluded.explanation, sort_order=excluded.sort_order;

on conflict (id) do update set topic_id=excluded.topic_id, prompt=excluded.prompt, options=excluded.options, answer_index=excluded.answer_index, explanation=excluded.explanation, sort_order=excluded.sort_order;

on conflict (id) do update set topic_id=excluded.topic_id, prompt=excluded.prompt, options=excluded.options, answer_index=excluded.answer_index, explanation=excluded.explanation, sort_order=excluded.sort_order;

on conflict (id) do update set topic_id=excluded.topic_id, prompt=excluded.prompt, options=excluded.options, answer_index=excluded.answer_index, explanation=excluded.explanation, sort_order=excluded.sort_order;

on conflict (id) do update set topic_id=excluded.topic_id, prompt=excluded.prompt, options=excluded.options, answer_index=excluded.answer_index, explanation=excluded.explanation, sort_order=excluded.sort_order;

on conflict (id) do update set topic_id=excluded.topic_id, prompt=excluded.prompt, options=excluded.options, answer_index=excluded.answer_index, explanation=excluded.explanation, sort_order=excluded.sort_order;

on conflict (id) do update set topic_id=excluded.topic_id, prompt=excluded.prompt, options=excluded.options, answer_index=excluded.answer_index, explanation=excluded.explanation, sort_order=excluded.sort_order;

on conflict (id) do update set topic_id=excluded.topic_id, prompt=excluded.prompt, options=excluded.options, answer_index=excluded.answer_index, explanation=excluded.explanation, sort_order=excluded.sort_order;

on conflict (id) do update set title=excluded.title, deck_type=excluded.deck_type, category_id=excluded.category_id, sort_order=excluded.sort_order, source_file=excluded.source_file;

on conflict (id) do update set deck_id=excluded.deck_id, prompt=excluded.prompt, options=excluded.options, answer_index=excluded.answer_index, sort_order=excluded.sort_order;

on conflict (deck_id, sort_order) do update set question=excluded.question, answer=excluded.answer;

on conflict (topic_id) do update set title=excluded.title, category_id=excluded.category_id, status=excluded.status, question_source=excluded.question_source, linked_topic_id=excluded.linked_topic_id, card_deck_id=excluded.card_deck_id, sort_order=excluded.sort_order;

on conflict (kadro) do update set duration_minutes=excluded.duration_minutes;

on conflict (kadro, topic_id) do update set question_count=excluded.question_count, sort_order=excluded.sort_order;

on conflict (id) do update set title=excluded.title, kadro=excluded.kadro, duration_minutes=excluded.duration_minutes, is_published=excluded.is_published, sort_order=excluded.sort_order;

on conflict (id) do update set deneme_id=excluded.deneme_id, prompt=excluded.prompt, options=excluded.options, answer_index=excluded.answer_index, sort_order=excluded.sort_order;

select setval(pg_get_serial_sequence('public.denemeler', 'id'), coalesce((select max(id) from public.denemeler), 1), true);
select setval(pg_get_serial_sequence('public.deneme_questions', 'id'), coalesce((select max(id) from public.deneme_questions), 1), true);
commit;
