insert into public.questions (id, topic_id, prompt, options, answer_index, explanation, sort_order) values
  ('1739-01', 'law-1739', '1739 sayılı Milli Eğitim Temel Kanunu''nun 2. maddesine göre Türk Milli Eğitiminin genel amacı ile ilgili aşağıdakilerden hangisi yanlıştır?', '["Atatürk ilke ve inkılaplarına, Atatürk milliyetçiliğine bağlı yurttaşlar yetiştirmek","Beden, zihin, ahlak, ruh ve duygu bakımından dengeli ve sağlıklı gelişmiş bir kişilik kazandırmak","Bireyleri yalnızca belirli bir mesleğe yönlendirip diğer alanlara kapatmak","İlgi, istidat ve kabiliyetlerini geliştirerek hayata ve üst öğrenime hazırlamak"]'::jsonb, 2, NULL, 1),
  ('1739-02', 'law-1739', 'Kanunun 4. maddesinde düzenlenen ''Genellik ve Eşitlik'' ilkesine göre eğitim kurumları kimlere açıktır?', '["Yalnızca Türk vatandaşı erkeklere","Dil, ırk, cinsiyet, engellilik ve din ayrımı gözetilmeksizin herkese","Sadece belirli bir gelir düzeyinin üzerindeki ailelerin çocuklarına","Yalnızca örgün eğitim çağındaki öğrencilere"]'::jsonb, 1, NULL, 2),
  ('1739-03', 'law-1739', '''Eğitimde hiçbir kişiye, aileye, zümreye veya sınıfa imtiyaz tanınamaz'' hükmü hangi temel ilke ile ilgilidir?', '["Süreklilik","Genellik ve eşitlik","Yöneltme","Bilimsellik"]'::jsonb, 1, NULL, 3),
  ('1739-04', 'law-1739', 'Fertlerin ilgi, istidat ve kabiliyetlerinin eğitim sürecinde belirlenerek yöneltilmesi hangi temel ilkenin konusudur?', '["Yöneltme","Fırsat ve imkan eşitliği","Planlılık","Karma eğitim"]'::jsonb, 0, NULL, 4),
  ('1739-05', 'law-1739', 'Milli eğitimde kadın erkek herkese aynı eğitim imkanının sağlanması esas olarak hangi ilkeyle ilgilidir?', '["Fırsat ve imkan eşitliği","Demokrasi eğitimi","Süreklilik","Bilimsellik"]'::jsonb, 0, NULL, 5),
  ('1739-06', 'law-1739', '''Fertlerin genel eğitimi belli başlı bir yaş ve devre ile sınırlı olmayıp hayat boyunca devam eder'' ifadesi hangi ilkenin özüdür?', '["Süreklilik","Genellik ve eşitlik","Yöneltme","Karma eğitim"]'::jsonb, 0, NULL, 6),
  ('1739-07', 'law-1739', 'Milli eğitim hizmetinin Atatürk inkılap ve ilkelerine ve Anayasada ifadesini bulan Atatürk milliyetçiliğine dayanması hangi ilke kapsamında düzenlenmiştir?', '["Atatürk İnkılap ve İlkeleri, Atatürk Milliyetçiliği","Laiklik","Bilimsellik","Planlılık"]'::jsonb, 0, NULL, 7),
