insert into public.flashcards (deck_id, question, answer, sort_order) values
  ('4483-sayili-kanun', '4483 sayılı Kanun hangi tarihte kabul edilmiştir?', '2 Aralık 1999', 1),
  ('4483-sayili-kanun', 'Kanun''un amacı nedir?', 'Memurlar ve diğer kamu görevlilerinin görevleri sebebiyle işledikleri suçlardan dolayı yargılanabilmeleri için izin vermeye yetkili mercileri ve izlenecek usulü düzenlemek', 2),
  ('4483-sayili-kanun', 'Kanun''un amacı hangi maddede düzenlenir?', 'Madde 1', 3),
  ('4483-sayili-kanun', '4483 sayılı Kanun, hangi eski kanunu yürürlükten kaldırmıştır?', '1913 tarihli Memurin Muhakematı Hakkında Kanunu Muvakkat', 4),
  ('4483-sayili-kanun', 'İlçede görevli memurlar hakkında soruşturma izni vermeye yetkili merci kimdir?', 'Kaymakam', 5),
  ('4483-sayili-kanun', 'İlde görevli memurlar hakkında soruşturma izni vermeye yetkili merci kimdir?', 'Vali', 6),
  ('4483-sayili-kanun', 'Bakanlık merkez teşkilatındaki memurlar için izin vermeye yetkili merci kimdir?', 'İlgili bakan', 7),
  ('4483-sayili-kanun', 'Yetkili merci, soruşturma izni konusundaki kararını normal şartlarda kaç gün içinde verir?', 'En geç 30 gün içinde', 8),
  ('4483-sayili-kanun', 'Bakanlıklarda soruşturma izni kararı için öngörülen süre kaç gündür?', 'En geç 60 gün', 9),
  ('4483-sayili-kanun', 'Soruşturma izni verilmesi veya verilmemesi kararına karşı nereye itiraz edilir?', 'Yetkili merciin bağlı bulunduğu bölge idare mahkemesine', 10),
  ('4483-sayili-kanun', 'Soruşturma izni kararına itiraz süresi kaç gündür?', '10 gün', 11),
  ('4483-sayili-kanun', 'Ön inceleme yapmakla görevlendirilen kişi(ler) kimler olabilir?', 'Denetim elemanları veya hakkında inceleme yapılanın üstü konumundaki memurlar', 12),
  ('4483-sayili-kanun', 'Kanun kapsamında memurlar dışında kimler de yer alır?', 'Diğer kamu görevlileri', 13),
  ('4483-sayili-kanun', 'Kanun, hangi tür suçlarla ilgili yargılanma usulünü düzenler?', 'Görevleri sebebiyle işlenen suçlar', 14),
  ('4483-sayili-kanun', 'İzin vermeye yetkili merciin kararı kimlere bildirilir?', 'Hakkında inceleme yapılan memura, varsa şikayetçiye ve Cumhuriyet başsavcılığına', 15),
  ('4483-sayili-kanun', 'Zamanaşımı süreleri işlemeye devam eder mi, yoksa durur mu?', 'Soruşturma izni sürecinde zamanaşımı işlemeye devam eder', 16),
  ('4483-sayili-kanun', 'Kanun kapsamı dışında tutulan bazı suçlar var mıdır?', 'Evet, bazı ağır suçlar (örneğin bazı Ceza Kanunu''nda sayılan suçlar) kanun kapsamı dışında tutulmuştur', 17),
  ('4483-sayili-kanun', '4483 sayılı Kanun kaç maddeden oluşur?', '17 madde (ek ve geçici maddelerle birlikte)', 18),
  ('4982-sayili-kanun', '4982 sayılı Bilgi Edinme Hakkı Kanunu hangi tarihte kabul edilmiştir?', '9 Ekim 2003', 1),
  ('4982-sayili-kanun', 'Kanun''un amacı hangi maddede düzenlenir?', 'Madde 1', 2),
  ('4982-sayili-kanun', 'Kanun''un amacı nedir?', 'Demokratik ve şeffaf yönetimin gereği olan eşitlik, tarafsızlık ve açıklık ilkelerine uygun şekilde bilgi edinme hakkını düzenlemek', 3),
  ('4982-sayili-kanun', 'Bilgi edinme başvurusu ne şekilde yapılabilir?', 'Yazılı olarak veya elektronik ortamda ya da diğer iletişim araçlarıyla', 4),
  ('4982-sayili-kanun', 'Kurum ve kuruluşlar başvurulara normal şartlarda en geç kaç iş günü içinde cevap verir?', 'En geç 15 iş günü', 5),
  ('4982-sayili-kanun', 'Başka bir birimden görüş alınmasını gerektiren başvurularda cevap süresi ne kadardır?', 'En geç 30 iş günü', 6),
  ('4982-sayili-kanun', 'Bilgi edinme başvurusunun reddi hangi hallerde mümkündür?', 'Devlet sırrı, ticari sır, özel hayatın gizliliği gibi istisnalar kapsamına giren bilgiler için', 7),
  ('4982-sayili-kanun', 'Başvurusu reddedilen kişi hangi kurula itiraz edebilir?', 'Bilgi Edinme Değerlendirme Kurulu''na', 8),
  ('4982-sayili-kanun', 'Bilgi Edinme Değerlendirme Kurulu kaç üyeden oluşur?', '9 üye', 9),
  ('4982-sayili-kanun', 'Bilgi edinme hakkı kimlere tanınmıştır?', 'Bilgi edinme hakkı; gerçek ve tüzel kişilere (Türk vatandaşları, Türkiye''de ikamet eden yabancılar ve karşılıklılık ilkesi çerçevesinde yabancı gerçek/tüzel kişiler) tanınmıştır', 10),
  ('4982-sayili-kanun', 'Devlet sırrı niteliğindeki bilgiler kanun kapsamında mıdır?', 'Hayır, istisna kapsamındadır ve verilmez', 11),
  ('4982-sayili-kanun', 'Kurum içi düzenlemeler niteliğindeki bilgi ve belgeler kanun kapsamında mıdır?', 'Kurum içi düzenleme niteliğindeki ve sadece kurum personelini ilgilendiren belgeler istisna kapsamındadır', 12),
  ('4982-sayili-kanun', 'Başvuru dilekçesinde hangi bilgiler bulunmalıdır?', 'Başvuranın adı-soyadı, imzası, oturma yeri veya iş adresi, başvurulan kurum ve istenen bilgi/belgenin açık şekilde belirtilmesi', 13),
  ('4982-sayili-kanun', 'Bilgi edinme başvurusunda bulunmak için herhangi bir gerekçe gösterme zorunluluğu var mıdır?', 'Hayır, gerekçe gösterme zorunluluğu yoktur', 14),
  ('5442-sayili-kanun', '5442 sayılı İl İdaresi Kanunu hangi tarihte kabul edilmiştir?', '10 Haziran 1949', 1),
  ('5442-sayili-kanun', 'Kanun''un 1. maddesi neyi düzenler?', 'Türkiye''nin merkezi idare kuruluşu bakımından illere, illerin de ilçelere bölünmesini', 2),
